  1 | import { useCallback, useRef, useState } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import {
  5 |   TitleBar,
  6 |   Playlist,
  7 |   PlayerControls,
  8 |   ProgressBar,
  9 |   StatusBar,
 10 |   DriveBrowser,
 11 | } from "./components";
 12 | import type { Track } from "./types";
 13 | 
 14 | function App() {
 15 |   const {
 16 |     state,
 17 |     play,
 18 |     pause,
 19 |     next,
 20 |     prev,
 21 |     seek,
 22 |     setVolume,
 23 |     addTrack,
 24 |     toggleShuffle,
 25 |     reorderPlaylist,
 26 |   } = usePlayerWithAudio([]);
 27 | 
 28 |   const { processFiles } = useMetadata();
 29 |   const [isLoading, setIsLoading] = useState(false);
 30 |   const [showDrive, setShowDrive] = useState(false);
 31 | 
 32 |   const fileInputRef = useRef<HTMLInputElement>(null);
 33 | 
 34 |   const handleSelectTrack = (track: Track) => {
 35 |     play(track);
 36 |   };
 37 | 
 38 |   const handleOpenFile = () => {
 39 |     fileInputRef.current?.click();
 40 |   };
 41 | 
 42 |   const handleFileChange = useCallback(
 43 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
 44 |       const files = e.target.files;
 45 |       if (!files || files.length === 0) return;
 46 | 
 47 |       setIsLoading(true);
 48 | 
 49 |       try {
 50 |         const fileArray = Array.from(files);
 51 |         const tracks = await processFiles(fileArray);
 52 | 
 53 |         for (const track of tracks) {
 54 |           addTrack(track);
 55 |         }
 56 | 
 57 |         // If nothing is playing, start with the first track
 58 |         if (!state.currentTrack && tracks.length > 0) {
 59 |           play(tracks[0]);
 60 |         }
 61 |       } catch (err) {
 62 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
 63 |       } finally {
 64 |         setIsLoading(false);
 65 |       }
 66 | 
 67 |       // Reset input so the same file can be selected again
 68 |       e.target.value = "";
 69 |     },
 70 |     [processFiles, addTrack, state.currentTrack, play]
 71 |   );
 72 | 
 73 |   const handleAddDriveTracks = useCallback(
 74 |     (tracks: Track[]) => {
 75 |       for (const track of tracks) {
 76 |         addTrack(track);
 77 |       }
 78 |       if (!state.currentTrack && tracks.length > 0) {
 79 |         play(tracks[0]);
 80 |       }
 81 |     },
 82 |     [addTrack, state.currentTrack, play]
 83 |   );
 84 | 
 85 |   return (
 86 |     <div className="app">
 87 |       <TitleBar />
 88 | 
 89 |       <main className="main-content">
 90 |         <div className="toolbar">
 91 |           <button
 92 |             className="toolbar-btn"
 93 |             onClick={handleOpenFile}
 94 |             disabled={isLoading}
 95 |             title="Abrir arquivo de áudio local"
 96 |           >
 97 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
 98 |           </button>
 99 |           <input
100 |             ref={fileInputRef}
101 |             type="file"
102 |             accept="audio/*"
103 |             multiple
104 |             style={{ display: "none" }}
105 |             onChange={handleFileChange}
106 |           />
107 |           <button
108 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
109 |             onClick={() => setShowDrive((v) => !v)}
110 |             title="Google Drive"
111 |           >
112 |             ☁️ Drive
113 |           </button>
114 |         </div>
115 | 
116 |         {showDrive && (
117 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
118 |         )}
119 | 
120 |         <Playlist
121 |           tracks={state.playlist}
122 |           currentTrackId={state.currentTrack?.id ?? null}
123 |           isPlaying={state.isPlaying}
124 |           onSelectTrack={handleSelectTrack}
125 |           onReorderPlaylist={reorderPlaylist}
126 |         />
127 | 
128 |         <PlayerControls
129 |           currentTrack={state.currentTrack}
130 |           isPlaying={state.isPlaying}
131 |           isShuffled={state.isShuffled}
132 |           onPlay={() => play()}
133 |           onPause={pause}
134 |           onNext={next}
135 |           onPrev={prev}
136 |           onToggleShuffle={toggleShuffle}
137 |         />
138 | 
139 |         <ProgressBar
140 |           currentTime={state.currentTime}
141 |           duration={state.duration}
142 |           onSeek={seek}
143 |         />
144 |       </main>
145 | 
146 |       <StatusBar
147 |         isPlaying={state.isPlaying}
148 |         volume={state.volume}
149 |         onVolumeChange={setVolume}
150 |       />
151 |     </div>
152 |   );
153 | }
154 | 
155 | export default App;
